require_once __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/functions.php';require_admin();
$stats=$pdo->query("SELECT COUNT(*) total,SUM(status='Reported') reported,SUM(status='Under Repair') repair,SUM(status='Resolved') resolved,SUM(severity='Critical' AND status<>'Resolved') critical FROM reports")->fetch();
$recent=$pdo->query("SELECT r.*,u.name citizen,t.team_name FROM reports r JOIN users u ON u.id=r.user_id LEFT JOIN teams t ON t.id=r.assigned_team_id ORDER BY r.created_at DESC LIMIT 8")->fetchAll();
$pageTitle='Admin panel';require __DIR__.'/../includes/header.php';
